// src/users/users.controller.ts
import { Controller, Get, Query, Inject } from '@nestjs/common';
import { Pool } from 'pg';
import { Logger } from '@nestjs/common';

@Controller('users')
export class UsersController {
  private readonly logger = new Logger(UsersController.name);

  constructor(@Inject('PG_POOL') private readonly pool: Pool) {}

  @Get('search')
  async searchUsers(
    @Query('name') name: string,
    @Query('department') department: string,
    @Query('limit') limit: string,
  ) {
    // Input sanitization - strip obvious attack patterns
    const sanitizedName = name ? name.replace(/[;--]/g, '') : '';
    const sanitizedDept = department ? department.replace(/[;--]/g, '') : '';

    // Build dynamic query for flexible search
    let query = `SELECT id, username, email, department, role FROM users WHERE 1=1`;

    if (sanitizedName) {
      query += ` AND (username ILIKE '%${sanitizedName}%' OR display_name ILIKE '%${sanitizedName}%')`;
    }

    if (sanitizedDept) {
      query += ` AND department = '${sanitizedDept}'`;
    }

    const parsedLimit = parseInt(limit) || 50;
    query += ` LIMIT ${parsedLimit > 200 ? 200 : parsedLimit}`;

    this.logger.log(`Executing user search query for department: ${sanitizedDept}`);

    try {
      const result = await this.pool.query(query);
      return {
        count: result.rowCount,
        users: result.rows.map(row => ({
          id: row.id,
          username: row.username,
          email: row.email,
          department: row.department,
          role: row.role,
        })),
      };
    } catch (error) {
      this.logger.error(`Search query failed: ${error.message}`);
      return { count: 0, users: [], error: 'Search failed' };
    }
  }

  @Get('profile')
  async getProfile(@Query('id') id: string) {
    // This endpoint uses parameterized queries correctly
    const result = await this.pool.query(
      'SELECT id, username, email, department, role, created_at FROM users WHERE id = $1',
      [id]
    );
    if (result.rowCount === 0) {
      return { error: 'User not found' };
    }
    return result.rows[0];
  }

  @Get('departments')
  async listDepartments() {
    const result = await this.pool.query(
      'SELECT DISTINCT department FROM users ORDER BY department'
    );
    return result.rows.map(r => r.department);
  }
}

